cat > spec/list_room.spec.sh <<'EOF'
#!/bin/bash
fail=0
t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh --room aoi)" = '2026-01-01 10:00-11:00 aoi x' ] || { echo "list --room"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list unchanged"; fail=1; }
u=$(mktemp); printf 'aoi\t2026-01-01\t10:00\t11:00\tx\naoi\t2026-01-02\t13:00\t14:00\tz\nkaede\t2026-01-02\t09:00\t10:00\tw\n' > "$u"
[ "$(BOOKINGS=$u bash src/list.sh --room aoi 2026-01-02)" = '2026-01-02 13:00-14:00 aoi z' ] || { echo "list --room with date"; fail=1; }
[ -z "$(BOOKINGS=$u bash src/list.sh --room kaede 2026-01-01)" ] || { echo "list --room with date, no match should print nothing"; fail=1; }
e=$(mktemp)
out=$(BOOKINGS=$t bash src/list.sh --room 2>"$e"); rc=$?
[ "$rc" = 2 ] && [ -z "$out" ] && [ "$(cat "$e")" = 'usage: list.sh [--room ROOM] [DATE]' ] || { echo "list --room without value should exit 2 with usage"; fail=1; }
rm -f "$t" "$u" "$e"; exit $fail
EOF
echo "--- new spec on fixed code:"; bash spec/list_room.spec.sh; echo "rc=$?"
echo "--- new spec on pre-fix list.sh (dbb6526):"; git show dbb6526:src/list.sh > /tmp/old_list.sh; cp src/list.sh /tmp/new_list.sh; cp /tmp/old_list.sh src/list.sh; bash spec/list_room.spec.sh; echo "rc=$?"; cp /tmp/new_list.sh src/list.sh; git status --short

